const members = await axios.get('https://randomuser.me/api/?results=10&seed=me&inc=name,email,picture');
const membersData = members.data.results.map(member => ({
  name: member.name.first +'' + member.name.last,
  email: member.email,
  picture: member.picture.medium,
}));

const memberListHtml = '<div class="member-list">';

for (const member of membersData) {
  const pictureTag = `<img class="member-picture" src="${member.picture}" width="100" height="100">`;
  const detailsTag = `<div class="member-details">Name: ${member.name}<br>Email: <a href="${member.email}">${member.email}</a></div>`;
  const listEntry = `<div class="${member.name}">${pictureTag}${detailsTag}</div>`;
  memberListHtml += listEntry + '<br>';
}

